    consumer.subscribe(List.of("orders"));

    while (true) {
        var records = consumer.poll(Duration.ofMillis(500));

        for (var r : records) {
            System.out.printf("p=%d o=%d key=%s value=%s%n",
                r.partition(), r.offset(), r.key(), r.value());
            handle(r);
        }
